class MyDataset(Dataset):
    def __init__(self, X, y):
        self.X = X
        self.y = y

    def __len__(self):
        return len(self.X)

    def __getitem__(self, idx):

        img = torch.tensor(self.X[idx]).permute(2, 0, 1).float() / 255.0
        label = self.y[idx]
        return img, label
